/bin/zsh -lc "python3 -c 'from pathlib import Path; import re; files=[Path(p) for p in [\"README.md\",\"DEVELOPMENT.md\",\"scripts/README.md\",\"evidence/development-history.md\"]]; problems=[]; count=0
for f in files:
 for target in re.findall(r\"\\[["'^'"\\]]*\\]\\((["'^)]+)'"\\)\",f.read_text()):
  if \"://\" in target: continue
  count+=1
  path,_,anchor=target.partition(\"#\"); dest=f.parent/path if path else f
  if not dest.exists(): problems.append(str(f)+\": missing \"+target)
  elif anchor and dest.suffix==\".md\":
   headings=re.findall(r\""'^#+'"\\s+(.+)"'$",dest.read_text(),re.M); anchors=[re.sub(r"[''^'"\\w\\- ]\",\"\",h.lower()).replace(\" \",\"-\") for h in headings]
   if anchor not in anchors: problems.append(str(f)+\": missing anchor \"+target)
print({\"local_links\":count,\"problems\":problems,\"OUTCOME.md_exists\":Path(\"OUTCOME.md\").exists()})'"
